var e = new Add(new Num(2), new Mul(new Num(3), new Num(4)));
Console.WriteLine(Eval(e, new()));

static double Eval(Expr e, Dictionary<string, double> vars) => e switch
{
    Num(var v) => v,
    _ => throw new NotSupportedException(),
};

abstract record Expr;
record Num(double Value) : Expr;
record Add(Expr Left, Expr Right) : Expr;
record Mul(Expr Left, Expr Right) : Expr;
